// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount == 10);
        vm.deal(address(this), amount);

        uint256 balanceBefore = address(c).balance;

        // Attempt to call play with the correct amount
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        uint256 balanceAfter = address(c).balance;

        // If the call succeeded, the pot must be consistent with the amounts
        if (success) {
            uint256 potAfter = c.pot();
            // The pot should be 0 if random was 0, or amount if random was 1
            // But the player sent amount, and pot increased by amount; if random=0, fee (1) goes to bank and the rest to player, pot becomes 0
            // If random=1, pot stays as amount (since nothing else happens)
            // So potAfter should be either 0 or amount (10)
            assertTrue(potAfter == 0 || potAfter == 10);
        }
    }
}

